import { useEffect, useMemo, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Activity, ArrowDown, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, Check, CheckCircle2, ChevronDown, CircleHelp, Copy, CreditCard, Globe2, Info, LayoutDashboard, Link2, Menu, Plus, RotateCcw, Search, Settings2, SlidersHorizontal, Wallet, Waypoints, X } from 'lucide-react';
import '../styles/workspace.css';

type Section = 'Overview' | 'Payments' | 'Routing' | 'Connectors' | 'Settings';
type Currency = 'EUR' | 'USD' | 'GBP';
type PaymentStatus = 'Succeeded' | 'Pending' | 'Failed' | 'Refunded';
type PaymentMethod = 'Visa' | 'Mastercard' | 'Apple Pay' | 'SEPA';
type TimelineEvent = { label: string; date: string; description: string };
type Payment = { id: string; customer: string; email: string; amount: number; currency: Currency; status: PaymentStatus; method: PaymentMethod; processor: string; date: string; order: string; timeline: TimelineEvent[] };
type Connector = { name: string; initial: string; color: string; enabled: boolean; description: string; methods: string[] };
type RoutingConfig = { allocations: number[]; currency: string; region: string; fallback: string; retry: boolean };
const CURRENCIES: Currency[] = ['EUR', 'USD', 'GBP'];
const CONNECTORS: Connector[] = [
  { name: 'Stripe', initial: 'S', color: '#635bff', enabled: true, description: 'Cards, wallets, and local payment methods.', methods: ['Cards', 'Wallets', 'SEPA'] },
  { name: 'Adyen', initial: 'a', color: '#138e4f', enabled: true, description: 'A global network for local payment experiences.', methods: ['Cards', 'Wallets', 'Local methods'] },
  { name: 'Checkout.com', initial: 'C', color: '#1d3557', enabled: true, description: 'Flexible card processing for growing businesses.', methods: ['Cards', 'Wallets'] },
  { name: 'PayPal', initial: 'P', color: '#0070e0', enabled: false, description: 'Let customers pay with their PayPal account.', methods: ['PayPal wallet'] },
  { name: 'Mollie', initial: 'm', color: '#171717', enabled: false, description: 'European payments, from cards to bank transfers.', methods: ['Cards', 'SEPA', 'Local methods'] },
  { name: 'Worldpay', initial: 'W', color: '#c4342c', enabled: false, description: 'Card processing across online and in-person channels.', methods: ['Cards', 'Wallets'] },
];
const INITIAL_ROUTING: RoutingConfig = { allocations: [60, 25, 15], currency: 'All currencies', region: 'All regions', fallback: 'Adyen', retry: true };
const NAV_ITEMS: { label: Section; icon: typeof LayoutDashboard }[] = [{ label: 'Overview', icon: LayoutDashboard }, { label: 'Payments', icon: CreditCard }, { label: 'Routing', icon: Waypoints }, { label: 'Connectors', icon: Link2 }, { label: 'Settings', icon: Settings2 }];
const CUSTOMERS = [['Olivia Martin', 'olivia@example.com'], ['Lucas Silva', 'lucas@example.com'], ['Sofia Laurent', 'sofia@example.com'], ['Noah Williams', 'noah@example.com'], ['Emma Jensen', 'emma@example.com'], ['Leo Costa', 'leo@example.com'], ['Mia Fischer', 'mia@example.com'], ['Amir Hassan', 'amir@example.com'], ['Isabella Rossi', 'isabella@example.com'], ['Hugo Santos', 'hugo@example.com'], ['Ella Wilson', 'ella@example.com'], ['Arthur Dubois', 'arthur@example.com']];
const METHODS: PaymentMethod[] = ['Visa', 'Mastercard', 'Apple Pay', 'SEPA'];

function money(amount: number, currency: Currency, compact = false) {
  return new Intl.NumberFormat('en-GB', { style: 'currency', currency, notation: compact ? 'compact' : 'standard', minimumFractionDigits: compact ? 0 : 2, maximumFractionDigits: compact ? 1 : 2 }).format(amount);
}
function dateLabel(date: string | Date, includeTime = false) {
  return new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', ...(includeTime ? { hour: '2-digit', minute: '2-digit' } : {}), timeZone: 'UTC' }).format(new Date(date));
}
function createDemoPayments(today: Date): Payment[] {
  const anchor = new Date(today); anchor.setUTCHours(0, 0, 0, 0);
  return Array.from({ length: 540 }, (_, i) => {
    const day = Math.floor(i / 3);
    const date = new Date(anchor.getTime() - day * 86400000 + ((i * 7 + 9) % 24) * 3600000 + ((i * 13) % 60) * 60000);
    const status: PaymentStatus = i % 19 === 9 ? 'Pending' : i % 17 === 7 ? 'Failed' : i % 31 === 13 ? 'Refunded' : 'Succeeded';
    const currency: Currency = i % 8 === 3 ? 'GBP' : i % 5 === 2 ? 'USD' : 'EUR';
    const customer = CUSTOMERS[(i * 7) % CUSTOMERS.length];
    const processor = CONNECTORS[i % 3].name;
    const timeline: TimelineEvent[] = [{ label: 'Payment created', date: date.toISOString(), description: 'Sample checkout submitted.' }];
    if (status === 'Pending') timeline.push({ label: 'Awaiting confirmation', date: new Date(date.getTime() + 1000).toISOString(), description: 'The demo payment is still pending.' });
    else if (status === 'Failed') timeline.push({ label: 'Payment declined', date: new Date(date.getTime() + 2000).toISOString(), description: 'Simulated decline: insufficient funds.' });
    else {
      timeline.push({ label: 'Payment accepted', date: new Date(date.getTime() + 2000).toISOString(), description: `Authorization simulated with ${processor}.` });
      if (status === 'Refunded') timeline.push({ label: 'Payment refunded', date: new Date(date.getTime() + 3600000).toISOString(), description: 'A full refund was simulated.' });
    }
    return { id: `avn_${(824931 - i * 37).toString(16)}${(i + 100).toString(16)}`, customer: customer[0], email: customer[1], amount: Number((24 + ((i * 73 + 117) % 697) + (i % 4) * .25).toFixed(2)), currency, status, method: METHODS[i % 4], processor, date: date.toISOString(), order: `ORD-${10482 - i}`, timeline };
  }).sort((a, b) => +new Date(b.date) - +new Date(a.date));
}
function BrandMark() {
  return <svg width="31" height="31" viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect x="13" y="6" width="8" height="37" rx="4" transform="rotate(20 17 24.5)" fill="currentColor"/><rect x="27" y="6" width="8" height="37" rx="4" transform="rotate(-20 31 24.5)" fill="currentColor"/><path d="M16 29.5H32" stroke="currentColor" strokeWidth="5" strokeLinecap="round"/></svg>;
}
function Status({ status }: { status: PaymentStatus }) {
  return <span className={`ws-status ws-status-${status.toLowerCase()}`}><span />{status}</span>;
}
function Dialog({ title, subtitle, children, onClose, drawer = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; drawer?: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const element = ref.current;
    const focusable = () => Array.from(element?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href], [tabindex="0"]') ?? []).filter(node => node.getClientRects().length > 0);
    (focusable()[0] ?? element)?.focus();
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
      if (event.key === 'Tab') {
        const nodes = focusable(); const first = nodes[0]; const last = nodes[nodes.length - 1];
        if (!nodes.length) { event.preventDefault(); element?.focus(); }
        else if (!element?.contains(document.activeElement)) { event.preventDefault(); first.focus(); }
        else if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    };
    const onFocusIn = (event: FocusEvent) => {
      if (!element?.contains(event.target as Node)) (focusable()[0] ?? element)?.focus();
    };
    const observer = new MutationObserver(() => {
      if (!element?.contains(document.activeElement)) (focusable()[0] ?? element)?.focus();
    });
    if (element) observer.observe(element, { childList: true, subtree: true });
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('focusin', onFocusIn);
    const overflow = document.body.style.overflow; document.body.style.overflow = 'hidden';
    return () => { observer.disconnect(); document.removeEventListener('keydown', onKeyDown); document.removeEventListener('focusin', onFocusIn); document.body.style.overflow = overflow; if (previous?.isConnected) previous.focus(); };
  }, [onClose]);
  return <div className={`ws-overlay ${drawer ? 'ws-overlay-drawer' : ''}`} onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div ref={ref} className={`ws-dialog ${drawer ? 'ws-drawer' : ''}`} role="dialog" aria-modal="true" aria-labelledby="ws-dialog-title" tabIndex={-1}><div className="ws-dialog-head"><div>{subtitle && <p className="ws-eyebrow">{subtitle}</p>}<h2 id="ws-dialog-title">{title}</h2></div><button className="ws-icon-button" aria-label="Close dialog" onClick={onClose}><X size={20}/></button></div>{children}</div></div>;
}
function VolumeChart({ payments, days, today, currency }: { payments: Payment[]; days: number; today: Date; currency: Currency }) {
  const [showData, setShowData] = useState(false);
  const numberOfBuckets = days === 7 ? 7 : days === 30 ? 10 : 9;
  const bucketDays = days / numberOfBuckets;
  const end = new Date(today); end.setUTCHours(23, 59, 59, 999);
  const start = new Date(end.getTime() - days * 86400000 + 1);
  const buckets = Array.from({ length: numberOfBuckets }, (_, i) => {
    const date = new Date(start.getTime() + i * bucketDays * 86400000);
    return { date, amount: payments.filter(payment => ['Succeeded', 'Refunded'].includes(payment.status) && +new Date(payment.date) >= +date && +new Date(payment.date) < +date + bucketDays * 86400000).reduce((sum, payment) => sum + payment.amount, 0) };
  });
  const max = Math.max(...buckets.map(bucket => bucket.amount), 100) * 1.22;
  const left = 90, right = 652, top = 20, bottom = 198;
  const points = buckets.map((bucket, i) => `${left + i * (right - left) / (buckets.length - 1)},${bottom - bucket.amount / max * (bottom - top)}`).join(' ');
  const total = buckets.reduce((sum, bucket) => sum + bucket.amount, 0);
  return <section className="ws-card ws-volume-card"><div className="ws-card-head"><div><h2>Processed volume</h2><p>Accepted payments over time</p></div><span className="ws-chart-legend"><span/>{currency}</span></div><div className="ws-chart-total">{money(total, currency)}<span>in the last {days} days</span></div><div className="ws-chart"><svg viewBox="0 0 680 236" role="img" aria-labelledby="ws-volume-title" aria-describedby="ws-volume-description"><title id="ws-volume-title">Demo processed payment volume in {currency}</title><desc id="ws-volume-description">{buckets.map(bucket => `${dateLabel(bucket.date)}: ${money(bucket.amount, currency)}`).join('. ')}</desc><defs><linearGradient id="ws-volume-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#a7ce97" stopOpacity=".48"/><stop offset="100%" stopColor="#dcebd4" stopOpacity=".06"/></linearGradient></defs>{[0, 1, 2, 3].map(i => { const y = top + i * (bottom - top) / 3; return <g key={i}><line x1={left} x2={right} y1={y} y2={y} stroke="#e7ece5" strokeDasharray="3 5"/><text x={left - 12} y={y + 4} textAnchor="end" fill="#7d8981" fontSize="11">{money(max * (1 - i / 3), currency, true)}</text></g>; })}<polygon points={`${left},${bottom} ${points} ${right},${bottom}`} fill="url(#ws-volume-fill)"/><polyline points={points} fill="none" stroke="#267052" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round"/>{buckets.map((bucket, i) => <circle key={i} cx={left + i * (right - left) / (buckets.length - 1)} cy={bottom - bucket.amount / max * (bottom - top)} r="3.3" fill="#fff" stroke="#267052" strokeWidth="2"><title>{dateLabel(bucket.date)}: {money(bucket.amount, currency)}</title></circle>)}{[0, Math.floor((buckets.length - 1) / 2), buckets.length - 1].map(i => <text key={i} x={left + i * (right - left) / (buckets.length - 1)} y="225" textAnchor={i === 0 ? 'start' : i === buckets.length - 1 ? 'end' : 'middle'} fill="#7d8981" fontSize="11">{dateLabel(buckets[i].date)}</text>)}</svg></div><div className="ws-chart-footer"><span>{bucketDays === 1 ? 'Daily totals' : `${bucketDays}-day totals`} · demo data</span><button className="ws-text-button" aria-expanded={showData} onClick={() => setShowData(!showData)}>{showData ? 'Hide data' : 'View data'}<ChevronDown size={14} className={showData ? 'ws-rotate' : ''}/></button></div>{showData && <div className="ws-chart-data"><table><caption className="ws-sr-only">Processed volume by date</caption><thead><tr><th scope="col">Period starting</th><th scope="col">Accepted volume</th></tr></thead><tbody>{buckets.map(bucket => <tr key={bucket.date.toISOString()}><td>{dateLabel(bucket.date)}</td><td>{money(bucket.amount, currency)}</td></tr>)}</tbody></table></div>}</section>;
}
function PaymentMethods({ payments, currency }: { payments: Payment[]; currency: Currency }) {
  const accepted = payments.filter(payment => ['Succeeded', 'Refunded'].includes(payment.status));
  const total = accepted.reduce((sum, payment) => sum + payment.amount, 0);
  const colors = ['#1d5c45', '#85ab78', '#bdd994', '#e0e9cf'];
  const methods = METHODS.map((method, i) => { const volume = accepted.filter(payment => payment.method === method).reduce((sum, payment) => sum + payment.amount, 0); return { name: method, volume, percentage: total ? volume / total * 100 : 0, color: colors[i] }; });
  let offset = 0;
  return <section className="ws-card ws-methods-card"><div className="ws-card-head"><div><h2>Payment methods</h2><p>Share of accepted volume</p></div><Wallet size={19} className="ws-muted"/></div><div className="ws-method-donut"><svg viewBox="0 0 160 160" role="img" aria-label={methods.map(method => `${method.name}: ${method.percentage.toFixed(1)}%`).join(', ')}><circle cx="80" cy="80" r="59" fill="none" stroke="#edf1e8" strokeWidth="17"/>{methods.map(method => { const currentOffset = offset; offset += method.percentage; return <circle key={method.name} cx="80" cy="80" r="59" fill="none" stroke={method.color} strokeWidth="17" pathLength="100" strokeDasharray={`${method.percentage} ${100 - method.percentage}`} strokeDashoffset={-currentOffset} transform="rotate(-90 80 80)"/>; })}</svg><div><strong>{accepted.length}</strong><span>accepted payments</span></div></div><div className="ws-method-list">{methods.map(method => <div className="ws-method-row" key={method.name}><span className="ws-method-label"><span style={{ background: method.color }}/>{method.name}</span><span><strong>{method.percentage.toFixed(1)}%</strong><small>{money(method.volume, currency)}</small></span></div>)}</div></section>;
}
function PaymentsTable({ payments, onSelect, compact = false }: { payments: Payment[]; onSelect: (id: string) => void; compact?: boolean }) {
  return <div className="ws-table-scroll"><table className="ws-payment-table"><caption className="ws-sr-only">{compact ? 'Recent demo payments' : 'Filtered demo payments'}</caption><thead><tr><th scope="col">Payment</th><th scope="col">Customer</th><th scope="col">Status</th><th scope="col" className="ws-table-amount">Amount</th><th scope="col">Processor</th><th scope="col">Date (UTC)</th><th scope="col"><span className="ws-sr-only">Details</span></th></tr></thead><tbody>{payments.length ? payments.map(payment => <tr key={payment.id} onClick={() => onSelect(payment.id)}><td><button className="ws-id-button" onClick={() => onSelect(payment.id)}>{payment.id}</button><span className="ws-table-small">{payment.order}</span></td><td><span className="ws-customer-name">{payment.customer}</span>{!compact && <span className="ws-table-small">{payment.email}</span>}</td><td><Status status={payment.status}/></td><td className="ws-table-amount"><strong>{money(payment.amount, payment.currency)}</strong></td><td><span className="ws-processor"><span className={`ws-processor-dot ws-processor-${payment.processor === 'Stripe' ? 'stripe' : payment.processor === 'Adyen' ? 'adyen' : 'checkout'}`}/>{payment.processor}</span></td><td><span className="ws-date">{dateLabel(payment.date)}</span><span className="ws-table-small">{new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'UTC' }).format(new Date(payment.date))}</span></td><td><button className="ws-row-action" aria-label={`View payment ${payment.id}`} onClick={() => onSelect(payment.id)}><ArrowUpRight size={17}/></button></td></tr>) : <tr><td colSpan={7}><div className="ws-empty-state"><Search size={25}/><strong>No payments found</strong><span>Try another search, status, or date range.</span></div></td></tr>}</tbody></table></div>;
}

export default function Workspace() {
  const [today] = useState(() => new Date());
  const [section, setSection] = useState<Section>('Overview');
  const [payments, setPayments] = useState(() => createDemoPayments(today));
  const [days, setDays] = useState(30);
  const [currency, setCurrency] = useState<Currency>('EUR');
  const [company, setCompany] = useState('Northstar Studio');
  const [companyDraft, setCompanyDraft] = useState('Northstar Studio');
  const [email, setEmail] = useState('finance@example.com');
  const [emailDraft, setEmailDraft] = useState('finance@example.com');
  const [currencyDraft, setCurrencyDraft] = useState<Currency>('EUR');
  const [connectors, setConnectors] = useState(CONNECTORS);
  const [routing, setRouting] = useState<RoutingConfig>(INITIAL_ROUTING);
  const [routingDraft, setRoutingDraft] = useState<RoutingConfig>(INITIAL_ROUTING);
  const [routingError, setRoutingError] = useState('');
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All statuses');
  const [paymentCurrency, setPaymentCurrency] = useState('All currencies');
  const [page, setPage] = useState(1);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [modal, setModal] = useState<'create' | 'help' | 'reset' | null>(null);
  const [managedConnector, setManagedConnector] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [toast, setToast] = useState('');
  const [copied, setCopied] = useState(false);
  const [refundConfirm, setRefundConfirm] = useState(false);
  const [createError, setCreateError] = useState('');
  const [settingsError, setSettingsError] = useState('');
  const contentRef = useRef<HTMLHeadingElement>(null);
  const closeDialog = useMemo(() => () => { setSelectedId(null); setModal(null); setManagedConnector(null); setRefundConfirm(false); setCopied(false); }, []);

  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 5500); return () => window.clearTimeout(timer); }, [toast]);
  useEffect(() => { setPage(1); }, [query, statusFilter, paymentCurrency, days]);
  const end = new Date(today); end.setUTCHours(23, 59, 59, 999);
  const start = new Date(end.getTime() - days * 86400000 + 1);
  const periodPayments = useMemo(() => payments.filter(payment => +new Date(payment.date) >= +start && +new Date(payment.date) <= +end), [payments, start.getTime(), end.getTime()]);
  const reportingPayments = periodPayments.filter(payment => payment.currency === currency);
  const accepted = reportingPayments.filter(payment => payment.status === 'Succeeded' || payment.status === 'Refunded');
  const attempted = reportingPayments.filter(payment => payment.status !== 'Pending');
  const volume = accepted.reduce((sum, payment) => sum + payment.amount, 0);
  const previousVolume = payments.filter(payment => payment.currency === currency && ['Succeeded', 'Refunded'].includes(payment.status) && +new Date(payment.date) < +start && +new Date(payment.date) >= +start - days * 86400000).reduce((sum, payment) => sum + payment.amount, 0);
  const volumeChange = previousVolume ? (volume / previousVolume - 1) * 100 : null;
  const filteredPayments = periodPayments.filter(payment => (statusFilter === 'All statuses' || payment.status === statusFilter) && (paymentCurrency === 'All currencies' || payment.currency === paymentCurrency) && `${payment.id} ${payment.customer} ${payment.email} ${payment.order} ${payment.processor}`.toLowerCase().includes(query.toLowerCase().trim()));
  const pageSize = 10, pageCount = Math.max(1, Math.ceil(filteredPayments.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const selectedPayment = payments.find(payment => payment.id === selectedId);
  const enabledConnectors = connectors.filter(connector => connector.enabled);
  const allocationTotal = routingDraft.allocations.reduce((sum, allocation) => sum + allocation, 0);

  function navigate(next: Section) { setSection(next); setMobileOpen(false); window.setTimeout(() => contentRef.current?.focus(), 0); }
  function exportCsv() {
    const fields = ['payment_id', 'order_id', 'customer', 'email', 'amount', 'currency', 'status', 'payment_method', 'processor', 'created_at_utc'];
    const rows = filteredPayments.map(payment => [payment.id, payment.order, payment.customer, payment.email, payment.amount.toFixed(2), payment.currency, payment.status, payment.method, payment.processor, payment.date]);
    const csv = [fields, ...rows].map(row => row.map(value => `"${String(value).replaceAll('"', '""')}"`).join(',')).join('\r\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }));
    const link = document.createElement('a'); link.href = url; link.download = `avenra-demo-payments-${days}d.csv`; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    setToast(`Exported ${filteredPayments.length} demo payments to CSV.`);
  }
  async function copyPaymentId(id: string) {
    try { await navigator.clipboard.writeText(id); setCopied(true); setToast('Payment ID copied.'); } catch { setToast('Copy is unavailable in this browser. Select the payment ID to copy it.'); }
  }
  function changePaymentStatus(payment: Payment, status: PaymentStatus) {
    const event: TimelineEvent = { label: status === 'Refunded' ? 'Demo refund completed' : 'Demo payment accepted', date: new Date().toISOString(), description: status === 'Refunded' ? 'Full refund simulated. No funds were moved.' : `Success simulated with ${payment.processor}. No funds were moved.` };
    setPayments(previous => previous.map(item => item.id === payment.id ? { ...item, status, timeline: [...item.timeline, event] } : item)); setRefundConfirm(false); setToast(status === 'Refunded' ? 'Demo payment refunded. No funds were moved.' : 'Demo payment marked as succeeded.');
  }
  function createPayment(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    const amount = Number(form.get('amount')); const name = String(form.get('customer') ?? '').trim();
    if (!Number.isFinite(amount) || amount <= 0 || amount > 1000000 || Math.abs(amount * 100 - Math.round(amount * 100)) > .00001) { setCreateError('Enter an amount between 0.01 and 1,000,000, with up to two decimal places.'); return; }
    if (!name) { setCreateError('Enter a customer name.'); return; }
    if (!enabledConnectors.some(connector => connector.name === form.get('processor'))) { setCreateError('Enable a connector before creating a demo payment.'); return; }
    const date = new Date().toISOString();
    const payment: Payment = { id: `avn_demo_${Date.now().toString(36)}`, customer: name, email: String(form.get('email')), amount, currency: String(form.get('currency')) as Currency, status: 'Pending', method: String(form.get('method')) as PaymentMethod, processor: String(form.get('processor')), date, order: `DEMO-${Date.now().toString().slice(-6)}`, timeline: [{ label: 'Demo payment created', date, description: 'A local payment was created. No request was sent to a processor.' }] };
    setPayments(previous => [payment, ...previous].sort((a, b) => +new Date(b.date) - +new Date(a.date))); setModal(null); setSelectedId(payment.id); setCreateError(''); setToast('Demo payment created. You can simulate its success in the details.');
  }
  function saveRouting(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (allocationTotal !== 100) { setRoutingError(`Allocations total ${allocationTotal}%. Adjust them to exactly 100%.`); return; }
    if (routingDraft.allocations.some((allocation, index) => allocation > 0 && !connectors[index].enabled)) { setRoutingError('A processor with an allocation is disabled. Enable it or set its allocation to 0%.'); return; }
    if (!enabledConnectors.some(connector => connector.name === routingDraft.fallback)) { setRoutingError('Choose an enabled fallback processor.'); return; }
    setRouting({ ...routingDraft, allocations: [...routingDraft.allocations] }); setRoutingError(''); setToast('Demo routing saved. This configuration is local to your session.');
  }
  function saveSettings(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const name = companyDraft.trim();
    if (!name) { setSettingsError('Enter a workspace name with at least one non-space character.'); return; }
    setCompany(name); setCompanyDraft(name); setEmail(emailDraft.trim()); setCurrency(currencyDraft); setSettingsError(''); setToast('Workspace settings saved for this demo session.');
  }
  function toggleConnector(name: string) {
    const connector = connectors.find(item => item.name === name)!;
    setConnectors(previous => previous.map(item => item.name === name ? { ...item, enabled: !item.enabled } : item));
    setToast(`${name} ${connector.enabled ? 'disabled' : 'enabled'} in the demo. No processor connection was made.`);
  }
  function resetDemo() {
    setPayments(createDemoPayments(today)); setConnectors(CONNECTORS); setRouting(INITIAL_ROUTING); setRoutingDraft(INITIAL_ROUTING); setRoutingError(''); setCompany('Northstar Studio'); setCompanyDraft('Northstar Studio'); setEmail('finance@example.com'); setEmailDraft('finance@example.com'); setCurrency('EUR'); setCurrencyDraft('EUR'); setSettingsError(''); setQuery(''); setStatusFilter('All statuses'); setPaymentCurrency('All currencies'); setDays(30); setModal(null); setToast('Demo reset to its original sample data.');
  }

  return <div className="ws-app">
    {mobileOpen && <button className="ws-sidebar-scrim" aria-label="Close navigation" onClick={() => setMobileOpen(false)}/>}
    <aside className={`ws-sidebar ${mobileOpen ? 'ws-sidebar-open' : ''}`}>
      <a className="ws-brand" href="/" aria-label="Avenra home"><BrandMark/><span>Avenra</span></a>
      <button className="ws-workspace-switch" onClick={() => navigate('Settings')} aria-label={`Workspace settings for ${company}`}><span className="ws-workspace-monogram">{company.split(' ').map(word => word[0]).join('').slice(0, 2).toUpperCase()}</span><span><strong>{company}</strong><small>Demo workspace</small></span><ChevronDown size={15}/></button>
      <span className="ws-nav-label">WORKSPACE</span>
      <nav aria-label="Merchant workspace"><ul>{NAV_ITEMS.map(item => <li key={item.label}><button className={`ws-nav-item ${section === item.label ? 'ws-nav-active' : ''}`} aria-current={section === item.label ? 'page' : undefined} onClick={() => navigate(item.label)}><item.icon size={19}/><span>{item.label}</span>{section === item.label && <span className="ws-nav-indicator"/>}</button></li>)}</ul></nav>
      <div className="ws-sidebar-bottom"><div className="ws-sandbox-card"><span className="ws-sandbox-icon"><Activity size={19}/></span><strong>A space to explore.</strong><p>Try payments and routing with sample data.</p><button onClick={() => setModal('help')}>About the demo<ArrowUpRight size={15}/></button></div><a className="ws-sidebar-home" href="/"><ArrowLeft size={16}/><span>Back to Avenra</span></a><div className="ws-sidebar-footer"><span className="ws-user-avatar">NS</span><span><strong>Workspace admin</strong><small>Demo access</small></span><button aria-label="Open workspace settings" onClick={() => navigate('Settings')}><Settings2 size={18}/></button></div></div>
    </aside>
    <div className="ws-main-shell">
      <header className="ws-topbar"><div className="ws-topbar-left"><button className="ws-icon-button ws-mobile-menu" aria-label="Open navigation" aria-expanded={mobileOpen} onClick={() => setMobileOpen(!mobileOpen)}><Menu size={21}/></button><span className="ws-breadcrumb-root">Workspace</span><span className="ws-breadcrumb-slash">/</span><span>{section}</span></div><div className="ws-topbar-actions"><span className="ws-demo-pill"><span/>Sandbox</span><button className="ws-icon-button" aria-label="About this demo workspace" onClick={() => setModal('help')}><CircleHelp size={20}/></button><button className="ws-topbar-avatar" aria-label="Workspace settings" onClick={() => navigate('Settings')}>NS</button></div></header>
      <main className="ws-content"><div className="ws-demo-notice"><Info size={16}/><span><strong>Demo workspace.</strong> Sample data, simulated actions, zero live transactions.</span><button onClick={() => setModal('help')}>Learn more<ArrowUpRight size={13}/></button></div>
        <div className="ws-page-heading"><div><h1 ref={contentRef} tabIndex={-1}>{section}</h1><p>{section === 'Overview' ? 'Every payment. One clear picture.' : section === 'Payments' ? 'The details behind every transaction.' : section === 'Routing' ? 'Give every payment a smarter path.' : section === 'Connectors' ? 'Your processors, connected in one place.' : 'Make this workspace your own.'}</p></div>{(section === 'Overview' || section === 'Payments') && <div className="ws-page-controls"><label className="ws-select-label"><span className="ws-sr-only">Date range</span><select value={days} onChange={event => setDays(Number(event.target.value))}><option value={7}>Last 7 days</option><option value={30}>Last 30 days</option><option value={90}>Last 90 days</option></select><ChevronDown size={15}/></label>{section === 'Overview' ? <label className="ws-select-label ws-currency-select"><span className="ws-sr-only">Reporting currency</span><select value={currency} onChange={event => { setCurrency(event.target.value as Currency); setCurrencyDraft(event.target.value as Currency); }}>{CURRENCIES.map(item => <option key={item}>{item}</option>)}</select><ChevronDown size={15}/></label> : <button className="ws-button ws-button-primary" onClick={() => { setCreateError(''); setModal('create'); }} disabled={!enabledConnectors.length}><Plus size={17}/>Create payment</button>}</div>}</div>

        {section === 'Overview' && <>
          <div className="ws-period-line"><span>{dateLabel(start)} – {dateLabel(end)}, {end.getUTCFullYear()}</span><span><span className="ws-live-dot"/>{currency} reporting · sample transactions</span></div>
          <div className="ws-metrics"><section className="ws-card ws-metric" aria-label="Processed volume"><div className="ws-metric-label"><span>Processed volume</span><span className="ws-metric-icon"><Wallet size={18}/></span></div><strong aria-label={money(volume, currency)} title={money(volume, currency)}>{money(volume, currency, volume >= 100000)}</strong><div className="ws-metric-foot">{volumeChange !== null ? <><span className={`ws-change ${volumeChange < 0 ? 'ws-change-down' : ''}`}>{volumeChange >= 0 ? <ArrowUpRight size={13}/> : <ArrowDown size={13}/>}{Math.abs(volumeChange).toFixed(1)}%</span><span>vs. previous {days} days</span></> : <span>No previous period data</span>}</div></section><section className="ws-card ws-metric" aria-label="Accepted payments"><div className="ws-metric-label"><span>Accepted payments</span><span className="ws-metric-icon"><CheckCircle2 size={18}/></span></div><strong>{accepted.length.toLocaleString()}</strong><div className="ws-metric-foot"><span>of {reportingPayments.length} sample payments</span></div></section><section className="ws-card ws-metric" aria-label="Acceptance rate"><div className="ws-metric-label"><span>Acceptance rate</span><span className="ws-metric-icon"><BarChart3 size={18}/></span></div><strong>{attempted.length ? (accepted.length / attempted.length * 100).toFixed(1) : '0.0'}<span className="ws-metric-unit">%</span></strong><div className="ws-metric-foot"><span>{attempted.length} completed attempts</span></div></section><section className="ws-card ws-metric" aria-label="Average payment"><div className="ws-metric-label"><span>Average payment</span><span className="ws-metric-icon"><CreditCard size={18}/></span></div><strong title={money(accepted.length ? volume / accepted.length : 0, currency)}>{money(accepted.length ? volume / accepted.length : 0, currency, accepted.length > 0 && volume / accepted.length >= 100000)}</strong><div className="ws-metric-foot"><span>per accepted payment</span></div></section></div>
          <div className="ws-overview-charts"><VolumeChart payments={reportingPayments} days={days} today={today} currency={currency}/><PaymentMethods payments={reportingPayments} currency={currency}/></div>
          <section className="ws-card ws-recent-card"><div className="ws-card-head"><div><h2>Recent payments</h2><p>Your latest {currency} activity at a glance</p></div><button className="ws-text-button" onClick={() => { setPaymentCurrency(currency); navigate('Payments'); }}>View all payments<ArrowRight size={16}/></button></div><PaymentsTable payments={reportingPayments.slice(0, 5)} onSelect={id => { setSelectedId(id); setRefundConfirm(false); }} compact/></section>
          <p className="ws-data-note">Accepted volume includes refunded authorizations. Pending payments are excluded from acceptance rate. Amounts are grouped by currency; no exchange rate is applied.</p>
        </>}

        {section === 'Payments' && <section className="ws-card ws-payments-card"><div className="ws-payments-toolbar"><label className="ws-search"><Search size={18}/><span className="ws-sr-only">Search payments</span><input aria-label="Search payments" placeholder="Search payment, customer, or order…" value={query} onChange={event => setQuery(event.target.value)}/>{query && <button aria-label="Clear payment search" onClick={() => setQuery('')}><X size={15}/></button>}</label><div className="ws-payment-filters"><label className="ws-select-label"><SlidersHorizontal size={15}/><span className="ws-sr-only">Payment status</span><select value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option>All statuses</option>{(['Succeeded', 'Pending', 'Failed', 'Refunded'] as PaymentStatus[]).map(status => <option key={status}>{status}</option>)}</select><ChevronDown size={14}/></label><label className="ws-select-label"><span className="ws-sr-only">Payment currency</span><select value={paymentCurrency} onChange={event => setPaymentCurrency(event.target.value)}><option>All currencies</option>{CURRENCIES.map(item => <option key={item}>{item}</option>)}</select><ChevronDown size={14}/></label><button className="ws-button ws-button-secondary" onClick={exportCsv}><ArrowDownToLine size={16}/><span>Export</span></button></div></div><div className="ws-results-label"><span><strong>{filteredPayments.length}</strong> demo payments</span><span>{dateLabel(start)} – {dateLabel(end)}</span></div><PaymentsTable payments={filteredPayments.slice((currentPage - 1) * pageSize, currentPage * pageSize)} onSelect={id => { setSelectedId(id); setRefundConfirm(false); }}/><div className="ws-pagination"><span>{filteredPayments.length ? `${(currentPage - 1) * pageSize + 1}–${Math.min(currentPage * pageSize, filteredPayments.length)} of ${filteredPayments.length} payments` : '0 payments'}</span><div><button className="ws-button ws-button-secondary" disabled={currentPage === 1} onClick={() => setPage(currentPage - 1)}><ArrowLeft size={14}/>Previous</button><span>Page {currentPage} of {pageCount}</span><button className="ws-button ws-button-secondary" disabled={currentPage === pageCount} onClick={() => setPage(currentPage + 1)}>Next<ArrowRight size={14}/></button></div></div></section>}

        {section === 'Routing' && <div className="ws-routing-layout"><div><section className="ws-card ws-routing-summary"><div className="ws-card-head"><div><h2>Payment routing</h2><p>A simple path. A resilient fallback.</p></div><span className="ws-neutral-badge">Demo configuration</span></div><div className="ws-routing-flow"><div><span className="ws-flow-icon"><CreditCard size={21}/></span><strong>Payment received</strong><small>{routing.currency}</small></div><ArrowRight size={22}/><div><span className="ws-flow-icon"><Waypoints size={21}/></span><strong>Smart allocation</strong><small>{routing.region}</small></div><ArrowRight size={22}/><div><span className="ws-flow-icon"><CheckCircle2 size={21}/></span><strong>Processor</strong><small>{routing.retry ? `${routing.fallback} fallback` : 'No automatic retry'}</small></div></div><div className="ws-allocation-bar" role="img" aria-label={routing.allocations.map((allocation, i) => `${CONNECTORS[i].name}: ${allocation}%`).join(', ')}>{routing.allocations.map((allocation, i) => allocation > 0 && <span key={i} style={{ width: `${allocation}%`, background: ['#1d5c45', '#94b980', '#d7e9b2'][i] }}/>)}</div><div className="ws-routing-key">{routing.allocations.map((allocation, i) => <span key={i}><i style={{ background: ['#1d5c45', '#94b980', '#d7e9b2'][i] }}/>{CONNECTORS[i].name}<strong>{allocation}%</strong></span>)}</div>{(routing.allocations.some((allocation, i) => allocation > 0 && !connectors[i].enabled) || !enabledConnectors.some(connector => connector.name === routing.fallback)) && <p className="ws-inline-warning"><Info size={16}/>An allocated or fallback connector is disabled. Update the rule before using this demo configuration.</p>}</section>
          <form className="ws-card ws-routing-editor" onSubmit={saveRouting}><div className="ws-card-head"><div><h2>Routing rule</h2><p>Adjust how demo payments are distributed.</p></div><span className="ws-rule-number">01</span></div><div className="ws-form-body"><div className="ws-form-grid"><label className="ws-field">Payment currency<select value={routingDraft.currency} onChange={event => setRoutingDraft({ ...routingDraft, currency: event.target.value })}><option>All currencies</option>{CURRENCIES.map(item => <option key={item}>{item}</option>)}</select></label><label className="ws-field">Customer region<select value={routingDraft.region} onChange={event => setRoutingDraft({ ...routingDraft, region: event.target.value })}><option>All regions</option><option>Europe</option><option>North America</option><option>Asia Pacific</option></select></label></div><div className="ws-form-section-head"><h3>Processor allocation</h3><span className={allocationTotal !== 100 ? 'ws-allocation-invalid' : ''}>{allocationTotal}% of 100%</span></div><p className="ws-field-hint">Distribute 100% of matching payments across your processors.</p>{routingDraft.allocations.map((allocation, index) => <div className="ws-allocation-input" key={CONNECTORS[index].name}><div className="ws-allocation-provider"><span className="ws-connector-mark" style={{ color: CONNECTORS[index].color, background: `${CONNECTORS[index].color}0d` }}>{CONNECTORS[index].initial}</span><span><strong>{CONNECTORS[index].name}</strong><small>{connectors[index].enabled ? 'Enabled in demo' : 'Disabled in demo'}</small></span></div><input aria-label={`${CONNECTORS[index].name} allocation`} type="range" min="0" max="100" step="1" value={allocation} onChange={event => { const allocations = [...routingDraft.allocations]; allocations[index] = Number(event.target.value); setRoutingDraft({ ...routingDraft, allocations }); setRoutingError(''); }}/><label className="ws-allocation-number"><span className="ws-sr-only">{CONNECTORS[index].name} allocation percent</span><input type="number" aria-label={`${CONNECTORS[index].name} allocation percent`} min="0" max="100" step="1" value={allocation} onChange={event => { const allocations = [...routingDraft.allocations]; allocations[index] = Math.min(100, Math.max(0, Math.round(Number(event.target.value)))); setRoutingDraft({ ...routingDraft, allocations }); setRoutingError(''); }}/><span>%</span></label></div>)}<div className="ws-form-section-head"><h3>Fallback</h3></div><label className="ws-field">If a processor is unavailable<select value={routingDraft.fallback} onChange={event => setRoutingDraft({ ...routingDraft, fallback: event.target.value })}>{enabledConnectors.map(connector => <option key={connector.name}>{connector.name}</option>)}{!enabledConnectors.some(connector => connector.name === routingDraft.fallback) && <option value={routingDraft.fallback}>{routingDraft.fallback} (disabled)</option>}</select></label><label className="ws-checkbox-field"><input type="checkbox" checked={routingDraft.retry} onChange={event => setRoutingDraft({ ...routingDraft, retry: event.target.checked })}/><span><strong>Retry with the fallback processor</strong><small>Simulate a retry for unavailable processors, rather than declined cards.</small></span></label>{routingError && <p className="ws-form-error" role="alert">{routingError}</p>}</div><div className="ws-form-footer"><span>Applies to this demo session only</span><div><button type="button" className="ws-button ws-button-secondary" onClick={() => { setRoutingDraft({ ...routing, allocations: [...routing.allocations] }); setRoutingError(''); setToast('Unsaved routing changes discarded.'); }}>Discard changes</button><button className="ws-button ws-button-primary" type="submit"><Check size={16}/>Save rule</button></div></div></form></div><aside className="ws-routing-aside"><section className="ws-card ws-tip-card"><span className="ws-tip-icon"><Waypoints size={24}/></span><h2>A better path for every payment.</h2><p>Spread payment traffic across processors and choose a fallback for availability issues.</p><div><CheckCircle2 size={16}/><span>Allocations must total 100%.</span></div><div><CheckCircle2 size={16}/><span>Only enabled processors can receive traffic.</span></div><div><CheckCircle2 size={16}/><span>Declined cards are not retried.</span></div><button className="ws-text-button" onClick={() => navigate('Connectors')}>Manage connectors<ArrowRight size={15}/></button></section><p className="ws-data-note">This editor illustrates routing configuration. It does not connect to the routing engine or affect sample payment history.</p></aside></div>}

        {section === 'Connectors' && <><div className="ws-connector-overview"><div><span className="ws-connector-stat">{enabledConnectors.length}</span><span><strong>Enabled in your demo</strong><small>Explore a multi-processor setup.</small></span></div><span className="ws-neutral-badge"><Globe2 size={14}/>6 sample connectors</span></div><div className="ws-connector-grid">{connectors.map(connector => <section className="ws-card ws-connector-card" key={connector.name} aria-label={`${connector.name} connector`}><div className="ws-connector-top"><span className="ws-connector-mark ws-connector-mark-large" style={{ color: connector.color, background: `${connector.color}0d` }}>{connector.initial}</span><span className={`ws-connector-state ${connector.enabled ? 'ws-connector-enabled' : ''}`}><span/>{connector.enabled ? 'Enabled' : 'Available'}</span></div><h2>{connector.name}</h2><p>{connector.description}</p><div className="ws-connector-tags">{connector.methods.map(method => <span key={method}>{method}</span>)}</div><div className="ws-connector-card-footer"><span>Demo connector</span><button className={`ws-button ${connector.enabled ? 'ws-button-secondary' : 'ws-button-primary'}`} onClick={() => setManagedConnector(connector.name)}>{connector.enabled ? 'Manage' : 'Enable'}<ArrowRight size={15}/></button></div></section>)}</div><div className="ws-connector-note"><Info size={18}/><p>Connector availability is illustrated with sample configurations. Enabling a connector updates this demo only; no credentials are requested or stored.</p></div></>}

        {section === 'Settings' && <div className="ws-settings-layout"><form className="ws-card ws-settings-card" onSubmit={saveSettings}><div className="ws-card-head"><div><h2>Workspace details</h2><p>The essentials for your payment operations.</p></div><Settings2 size={19} className="ws-muted"/></div><div className="ws-form-body"><label className="ws-field">Workspace name<input value={companyDraft} onChange={event => setCompanyDraft(event.target.value)} required maxLength={50} minLength={1}/><span className="ws-field-hint">Shown in the workspace navigation.</span></label><label className="ws-field">Finance email<input type="email" value={emailDraft} onChange={event => setEmailDraft(event.target.value)} required maxLength={150}/><span className="ws-field-hint">A demo contact field. No emails will be sent.</span></label><label className="ws-field">Reporting and default payment currency<select value={currencyDraft} onChange={event => setCurrencyDraft(event.target.value as Currency)}><option value="EUR">EUR — Euro</option><option value="USD">USD — US dollar</option><option value="GBP">GBP — British pound</option></select><span className="ws-field-hint">Overview reports payments in this currency. New demo payments use it by default.</span></label>{settingsError && <p className="ws-form-error" role="alert">{settingsError}</p>}</div><div className="ws-form-footer"><span>Saved locally for this session</span><button className="ws-button ws-button-primary" type="submit"><Check size={16}/>Save changes</button></div></form><aside><section className="ws-card ws-settings-summary"><span className="ws-workspace-monogram">{company.split(' ').map(word => word[0]).join('').slice(0, 2).toUpperCase()}</span><h2>{company}</h2><p>{email}</p><span className="ws-demo-pill"><span/>Demo workspace</span><dl><div><dt>Workspace ID</dt><dd>ws_demo_northstar</dd></div><div><dt>Reporting currency</dt><dd>{currency}</dd></div><div><dt>Environment</dt><dd>Local demo</dd></div></dl></section><section className="ws-card ws-reset-card"><h2>Start fresh</h2><p>Restore the original sample payments, connectors, routing, and workspace details.</p><button className="ws-button ws-button-secondary" onClick={() => setModal('reset')}><RotateCcw size={16}/>Reset demo</button></section></aside></div>}
        <footer className="ws-content-footer"><span><BrandMark/>Avenra workspace</span><span>Built for a clearer view.</span></footer>
      </main>
    </div>

    {selectedPayment && <Dialog title="Payment details" subtitle="DEMO PAYMENT" drawer onClose={closeDialog}><div className="ws-payment-detail"><div className="ws-detail-amount"><strong>{money(selectedPayment.amount, selectedPayment.currency)}</strong><Status status={selectedPayment.status}/></div><div className="ws-detail-id"><span>{selectedPayment.id}</span><button className="ws-icon-button" aria-label="Copy payment ID" onClick={() => copyPaymentId(selectedPayment.id)}>{copied ? <Check size={17}/> : <Copy size={17}/>}</button></div><dl className="ws-detail-grid"><div><dt>Customer</dt><dd>{selectedPayment.customer}<span>{selectedPayment.email}</span></dd></div><div><dt>Order reference</dt><dd>{selectedPayment.order}</dd></div><div><dt>Payment method</dt><dd><CreditCard size={16}/>{selectedPayment.method}</dd></div><div><dt>Processor</dt><dd>{selectedPayment.processor}</dd></div><div><dt>Created (UTC)</dt><dd>{dateLabel(selectedPayment.date, true)}, {new Date(selectedPayment.date).getUTCFullYear()}</dd></div><div><dt>Environment</dt><dd>Local demo</dd></div></dl><div className="ws-timeline"><h3>Payment timeline</h3><ol>{selectedPayment.timeline.map((event, index) => <li key={`${event.label}-${index}`}><span className="ws-timeline-dot"><Check size={11}/></span><div><strong>{event.label}</strong><p>{event.description}</p><time dateTime={event.date}>{dateLabel(event.date, true)} UTC</time></div></li>)}</ol></div><div className="ws-detail-actions">{selectedPayment.status === 'Pending' && <button className="ws-button ws-button-primary" onClick={() => changePaymentStatus(selectedPayment, 'Succeeded')}><CheckCircle2 size={17}/>Simulate success</button>}{selectedPayment.status === 'Succeeded' && (!refundConfirm ? <button className="ws-button ws-button-secondary" onClick={() => setRefundConfirm(true)}><RotateCcw size={16}/>Simulate refund</button> : <div className="ws-refund-confirm"><strong>Simulate a full refund?</strong><p>{money(selectedPayment.amount, selectedPayment.currency)} will be marked as refunded in this demo.</p><div><button className="ws-button ws-button-secondary" onClick={() => setRefundConfirm(false)}>Cancel</button><button className="ws-button ws-button-primary" onClick={() => changePaymentStatus(selectedPayment, 'Refunded')}>Confirm demo refund</button></div></div>)}<p><Info size={14}/>These actions update sample data only. No money moves.</p></div></div></Dialog>}
    {modal === 'create' && <Dialog title="Create a demo payment" subtitle="TRY YOUR WORKSPACE" onClose={closeDialog}><form onSubmit={createPayment} className="ws-create-form"><p className="ws-dialog-description">Add a pending sample payment, then simulate its success from the payment details.</p><div className="ws-form-grid"><label className="ws-field">Amount<input name="amount" type="number" min="0.01" max="1000000" step="0.01" placeholder="149.00" required autoFocus/></label><label className="ws-field">Currency<select name="currency" defaultValue={currency}>{CURRENCIES.map(item => <option key={item}>{item}</option>)}</select></label></div><label className="ws-field">Customer name<input name="customer" placeholder="Alex Morgan" maxLength={100} required/></label><label className="ws-field">Customer email<input name="email" type="email" placeholder="alex@example.com" maxLength={150} required/></label><div className="ws-form-grid"><label className="ws-field">Payment method<select name="method">{METHODS.map(method => <option key={method}>{method}</option>)}</select></label><label className="ws-field">Processor<select name="processor" required>{enabledConnectors.map(connector => <option key={connector.name}>{connector.name}</option>)}</select></label></div>{createError && <p className="ws-form-error" role="alert">{createError}</p>}<div className="ws-dialog-actions"><button type="button" className="ws-button ws-button-secondary" onClick={closeDialog}>Cancel</button><button type="submit" className="ws-button ws-button-primary" disabled={!enabledConnectors.length}><Plus size={16}/>Create demo payment</button></div><p className="ws-modal-note"><Info size={14}/>No payment request is sent. All details stay in this session.</p></form></Dialog>}
    {modal === 'help' && <Dialog title="Your space to explore" subtitle="WELCOME TO AVENRA" onClose={closeDialog}><div className="ws-help-content"><p>This merchant workspace uses generated sample payments to show how payment operations can come together.</p><ul><li><CreditCard size={20}/><div><strong>Explore payment activity</strong><span>Change date ranges, search transactions, export a CSV, or simulate a payment and refund.</span></div></li><li><Waypoints size={20}/><div><strong>Find the right payment path</strong><span>Edit processor allocations and fallback settings in the routing demo.</span></div></li><li><Link2 size={20}/><div><strong>Shape your workspace</strong><span>Enable sample connectors and change your workspace details.</span></div></li></ul><div className="ws-help-callout"><Info size={17}/><span>There is no live API connection. Changes are held in this browser session and reset when you reload the page. No real credentials or funds are involved.</span></div><button className="ws-button ws-button-primary" onClick={closeDialog}>Got it<ArrowRight size={16}/></button></div></Dialog>}
    {modal === 'reset' && <Dialog title="Reset your demo?" subtitle="START FRESH" onClose={closeDialog}><p className="ws-dialog-description">This restores the original sample data and removes the payments, settings, and routing changes you made in this session.</p><div className="ws-dialog-actions"><button className="ws-button ws-button-secondary" onClick={closeDialog}>Keep my changes</button><button className="ws-button ws-button-primary" onClick={resetDemo}><RotateCcw size={16}/>Reset demo</button></div></Dialog>}
    {managedConnector && <Dialog title={managedConnector} subtitle="DEMO CONNECTOR" onClose={closeDialog}><div className="ws-manage-connector"><div className="ws-manage-status"><span className={`ws-connector-state ${connectors.find(connector => connector.name === managedConnector)?.enabled ? 'ws-connector-enabled' : ''}`}><span/>{connectors.find(connector => connector.name === managedConnector)?.enabled ? 'Enabled in demo' : 'Available to enable'}</span></div><p>{connectors.find(connector => connector.name === managedConnector)?.description}</p><div className="ws-help-callout"><Info size={17}/><span>This is a simulated connector. Enabling it makes it available in the demo payment and routing forms. It does not connect an account or request API credentials.</span></div><div className="ws-dialog-actions"><button className="ws-button ws-button-secondary" onClick={closeDialog}>Close</button><button className="ws-button ws-button-primary" onClick={() => { toggleConnector(managedConnector); setManagedConnector(null); }}>{connectors.find(connector => connector.name === managedConnector)?.enabled ? 'Disable in demo' : 'Enable in demo'}<ArrowRight size={16}/></button></div></div></Dialog>}
    {toast && <div className="ws-toast" role="status"><CheckCircle2 size={19}/><span>{toast}</span><button aria-label="Dismiss notification" onClick={() => setToast('')}><X size={16}/></button></div>}
  </div>;
}
